  /* 3.0.7 · 只认 B 站「网页全屏」按钮，绝不返回系统全屏按钮。
     3.0.6 的 other 兜底会把系统全屏按钮自己也返回，click 它绕回 capture
     被 fsRedirecting 吞掉 → 「点了没反应」；而且系统全屏没有弹幕/控制栏。
     网页全屏是 B 站自己切 CSS 状态，DOM、弹幕层、控制栏、手势全保留。 */
  function biliFullscreenBtn() {
    const webSels = [
      '.bpx-player-ctrl-web-fullscreen', '[class*="web-fullscreen"]',
      '[class*="web-full"]', '[class*="webfull"]', '[class*="web_full"]',
      '[title*="网页全屏"]', '[aria-label*="网页全屏"]', '[data-title*="网页全屏"]',
      '[title*="Web Fullscreen"]', '[aria-label*="Web Fullscreen"]'
    ];
    const isWeb = (e) => {
      let sig = '';
      try {
        sig = (typeof e.className === 'string' ? e.className : '') + ' ' +
          (e.getAttribute('title') || '') + ' ' + (e.getAttribute('aria-label') || '') + ' ' +
          (e.getAttribute('data-title') || '') + ' ' + (e.getAttribute('data-tooltip') || '');
      } catch (_) { return false; }
      /* 明确排除系统全屏 / 退出全屏 */
      if (/ctrl-full(?!-)|fullscreen(?!.*web)|系统全屏|exit-full|退出全屏/i.test(sig) &&
          !/web-full|webfull|web_full|网页全屏|web fullscreen/i.test(sig)) return false;
      return /web-full|webfull|web_full|网页全屏|web fullscreen/i.test(sig);
    };
    let el = firstMatch(webSels);
    if (el && isWeb(el)) return el;
    /* 兜底：播放器常在 shadow DOM 里，遍历所有 root 找网页全屏控件。
       只收明确带 web 标识的，宁可返回 null 也不碰系统全屏按钮。 */
    try {
      const web = [];
      collectRoots().forEach(r => {
        try {
          r.querySelectorAll('button,[role="button"],[class*="ctrl"],[class*="btn"],' +
            '[title],[aria-label],[data-title]').forEach(e => {
            if (!/exit|退出/i.test(String(e.getAttribute('title') || '') +
              String(e.getAttribute('aria-label') || '')) && isWeb(e)) web.push(e);
          });
        } catch (_) {}
      });
      if (web.length) return web[0];
    } catch (e) {}
    return null;
  }
  function currentMode() {
    const m = CFG.fillMode || 'auto';
    if (m !== 'auto') return m;
    const v = findVideo();
    const w = v && v.videoWidth, h = v && v.videoHeight;
    if (window.innerHeight > window.innerWidth * 1.05) return 'contain'; /* 4.1.1：竖屏屏按「画面宽=屏宽」完整显示+上下黑边；旧逻辑只看视频方向，横屏片恒判 cover 会把画面放大到屏高、左右裁成中央一条竖条。下方保留「竖屏/方屏片 contain、横屏屏 cover 消灭 4:3 黑边」 */
    return (w && h && h > w * 1.05) ? 'contain' : 'cover';
  }
  function biggestPlayerRect() {
    const v = findVideo(); if (!v) return null;
    let el = v, best = null;
    for (let i = 0; i < 6 && el && el.parentElement; i++) {
      el = el.parentElement;
      // v2.1.4：body / html 本来就是 100vw 宽且常常高于视口，算进去会让
      // 普通观看页被误判成「已全屏」→ 铺满增强与整屏热区提前生效。
      if (el === document.body || el === document.documentElement) break;
      if (!el.getBoundingClientRect) continue;
      const r = el.getBoundingClientRect();
      if (!best || (r.width * r.height) > (best.width * best.height)) best = r;
      if (r.width >= window.innerWidth * 0.98 && r.height >= window.innerHeight * 0.96) return r;
    }
    return best;
  }
