    try {
      (deepFind('button, a, [role="button"]') || []).forEach(el => {
        const t = String(el.textContent || '').trim();
        if ((t === '换一换' || t === '刷新内容') && raw.indexOf(el) < 0) raw.push(el);
      });
    } catch (e) {}
    diag.candidates = raw.length;
