      if (!btn) {
        diag.result = '未找到换一换';
        CORE.refreshDiag = diag;
        toast('️ 没找到「换一换」按钮，未执行刷新 · 可复制「刷新诊断」给我定位');
        return;
      }
      // ① 原生 click
      try { btn.click(); diag.steps.push('native click'); } catch (e) { diag.steps.push('native click 失败：' + e.message); }
      let after = await waitFeedChange(before, 1400);
      // ② 完整事件序列（Vue 组件常只认这个）
