  function dmToastText(after) {
    let st = 'off';
    try {
      if (window.__IBILI_DM_STATE__) st = window.__IBILI_DM_STATE__();
      else if (after && after.on === true) st = 'on';
    } catch (e) { if (after && after.on === true) st = 'on'; }
    try { return window.__IBILI_DM_TEXT__(st); }
    catch (e) { return st === 'on' ? '弹幕已开' : (st === 'half' ? '弹幕已半开' : '弹幕已关'); }
  }
