    const box = fsEl('.bpe-search');
    if (!box) return;
    if (CORE.nativeSearch.open) closeNativeSearch('打开浮层前先复原', { silent: true });
    if (host) host.style.zIndex = '2147483647';
    box.hidden = false;
    f.open = true; f.suggest = []; f.sugIndex = -1; f.sugSeq++;
