      let c = '';
      if (f.counts) {
        const ci = t.id === 'media_bangumi' ? 'media_bangumi' : t.id === 'media_ft' ? 'media_ft' : t.id;
        c = fsCount(f.counts[ci]);
      }
      return '<button class="bpe-fs-tab ' + (f.tab === t.id ? 'on' : '') + '" data-act="fstab:' + t.id + '">' +
        esc(t.label) + (c ? '<i>' + esc(c) + '</i>' : '') + '</button>';
