      const undo = document.createElement('button');
      undo.type = 'button'; undo.className = 'bpe-removed-undo';
      /* P1-Y · 禁止 emoji / 几何字符：用内嵌 SVG 还原箭头 */
      const ico = iconSvg('undo');
