  /* P1-T ④：BP_NATIVE_I18N 的 2812 键只有 9 语，ko/th/vi/id 缺整语；
     不硬补 2812×4 机翻（会编造译文）。这里从 BP_LOCALES 里已有的 11 语
     人工译文反查：把「中文源文」对上 zh-CN 的值，取该 key 在本地语的值，
     合并到英文底表之上。命中项显示本地语，未命中仍回退英文（行为不变），
     零译文创作、零字典体积膨胀。 */
  (function () {
    var N = window.BP_NATIVE_I18N, L = window.BP_LOCALES;
    if (!N || !L) return;
    var zh = L['zh-CN'] || {}, en = N.en || {}, byText = {};
    Object.keys(zh).forEach(function (k) {
      var v = zh[k];
      if (typeof v === 'string' && v && !byText[v]) byText[v] = k;
    });
    var diag = {};
    ['ko', 'th', 'vi', 'id'].forEach(function (id) {
      var d = L[id] || {}, out = {};
      Object.keys(en).forEach(function (cn) {
        var k = byText[cn]; if (!k) return;
        var v = d[k];
        if (typeof v === 'string' && v && v !== cn) out[cn] = v;
      });
      N[id] = Object.assign({}, en, N[id] || {}, out);
      diag[id] = Object.keys(out).length;
    });
    try { window.__IBILI_NATIVE_DERIVED__ = diag; } catch (e) {}
  })();
