      const allShortcuts = SHORTCUTS.slice();
      extraKeys.forEach(k => allShortcuts.push([k, k === 'dmInput' ? (window.BP_DM412_T ? window.BP_DM412_T('key_dmInput', '弹幕输入 / 预设') : '弹幕输入 / 预设') : 'raw:' + (window.BP_KEY414 ? window.BP_KEY414.T(k) : k)]));
